const normalize = (value: string | null) => value?.trim().toLocaleLowerCase() ?? "";
const externalUrl = (item: PaperPatentMatch) => item.kind === "paper" ? `https://doi.org/${item.external_id}` : `https://patents.google.com/patent/${item.external_id}`;
const nextId = (ids: string[]) => `pp-${String(Math.max(0, ...ids.map(id => Number(id.match(/\d+/)?.[0] ?? 0))) + 1).padStart(3, "0")}`;
export const downloadBulkEvidenceTemplate = (kind: LookupKind) => { const sheet = XLSX.utils.aoa_to_sheet([["ID", "Feedstock", "Process", "Product", "Application", "Note"], [kind === "paper" ? "10.1234/example" : "EP1234567A1", "Wheat straw", "Fermentation", "Lactic acid", "", "Optional note"]]); const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, sheet, kind === "paper" ? "Papers" : "Patents"); XLSX.writeFile(workbook, `bulk-${kind}-template.xlsx`); };
type DecidedStatus = Exclude<ReviewStatus, "review_pending">;
type DecisionTarget = { ids: string[]; status: DecidedStatus } | null;
type SortKey = "default" | "scope" | "pathways";
type ScopeFilter = "all" | "production" | "application" | "both" | "none";

function KindChip({ kind }: { kind: LookupKind }) { const Icon = kind === "paper" ? FileText : ScrollText; return <Badge variant="outline" className="h-5 gap-1 whitespace-nowrap text-[9px] font-normal text-muted-foreground"><Icon className="h-3 w-3" />{kind === "paper" ? "Paper" : "Patent"}</Badge>; }
function FilterSelect({ value, onChange, label, children, className }: { value: string; onChange: (value: string) => void; label: string; children: React.ReactNode; className?: string }) { return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className={cn("h-8 w-44 text-[10px]", className)}><SelectValue /></SelectTrigger><SelectContent>{children}</SelectContent></Select>; }
function Truncated({ value, className }: { value: string | null; className?: string }) { return value ? <Tooltip><TooltipTrigger asChild><span className={cn("block max-w-52 truncate text-[10px]", className)}>{value}</span></TooltipTrigger><TooltipContent className="max-w-md text-xs">{value}</TooltipContent></Tooltip> : <ValueCell value={null} />; }

function MatchEditor({ nodes, note, onNodes, onNote }: { nodes: MatchNodes; note: string; onNodes: (value: MatchNodes) => void; onNote: (value: string) => void }) {
  return <div className="space-y-4"><div><Label className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Matched nodes</Label><div className="mt-1"><NodeFields value={nodes} onChange={onNodes} /></div></div><div><Label className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Note (optional)</Label><Input className="mt-1 h-9 text-xs" value={note} onChange={event => onNote(event.target.value)} /></div><div><div className="mb-2 flex items-center justify-between"><h3 className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Live Pathway preview</h3><ScopeSummary match={{ nodes }} /></div><DerivedPathwayList match={{ nodes }} /></div></div>;
}

export function MatchReviewSection({ kind }: { kind: LookupKind }) {
  const [decision, setDecision] = useState<DecisionTarget>(null); const [editId, setEditId] = useState<string | null>(null); const [detailId, setDetailId] = useState<string | null>(null); const [addOpen, setAddOpen] = useState(false); const [bulkOpen, setBulkOpen] = useState(false);
  return <><MatchesTable kind={kind} onDecision={(ids, status) => setDecision({ ids, status })} onEdit={setEditId} onDetail={setDetailId} onAdd={() => setAddOpen(true)} onBulkAdd={() => setBulkOpen(true)} /><DecisionDialog kind={kind} target={decision} onClose={() => setDecision(null)} /><EditNodesDialog kind={kind} matchId={editId} onClose={() => setEditId(null)} /><LookupDialog kind={kind} open={addOpen} onClose={() => setAddOpen(false)} onOpenExisting={setDetailId} /><BulkAddDialog kind={kind} open={bulkOpen} onClose={() => setBulkOpen(false)} onOpenExisting={id => { setBulkOpen(false); setDetailId(id); }} /><MatchDetailSheet kind={kind} matchId={detailId} onClose={() => setDetailId(null)} onDecision={(ids, status) => setDecision({ ids, status })} onEdit={setEditId} /></>;
}

function MatchesTable({ kind, onDecision, onEdit, onDetail, onAdd, onBulkAdd }: { kind: LookupKind; onDecision: (ids: string[], status: DecidedStatus) => void; onEdit: (id: string) => void; onDetail: (id: string) => void; onAdd: () => void; onBulkAdd: () => void }) {
  const store = useHitlStore(); const { openHistory } = useHistorySheet(); const nodeFilter = useNodeFilter(); const entityType = kind === "paper" ? "paper_match" : "patent_match";
  const [search, setSearch] = useState(""); const [status, setStatus] = useState("all"); const [nodeState, setNodeState] = useState("all"); const [scope, setScope] = useState<ScopeFilter>("all"); const [sort, setSort] = useState<SortKey>("default"); const [selected, setSelected] = useState<string[]>([]);
  const filtered = useMemo(() => store.paperPatentMatches.filter(item => { const ids = derivedPathwayIds(item, store.pathways); const summaries = ids.map(id => { const pathway = store.pathways.find(row => row.id === id); return pathway ? pathwayScope(item, pathway) : null; }).filter(Boolean); const nodeValues = matchNodePositions.map(position => item.nodes[position]).filter((value): value is string => Boolean(value)); const haystack = [item.title, item.external_id, item.authors_or_assignee, item.note, ...nodeValues, ...ids.flatMap(id => { const p = store.pathways.find(row => row.id === id); return p ? [p.feedstock, p.process_technology, p.product, p.application_market] : []; })].join(" ").toLocaleLowerCase(); const direct = (!nodeFilter.feedstock || normalize(item.nodes.feedstock) === normalize(nodeFilter.feedstock)) && (!nodeFilter.product || normalize(item.nodes.product) === normalize(nodeFilter.product)); const scopePass = scope === "all" || (scope === "none" ? ids.length === 0 : scope === "production" ? summaries.some(value => value?.production) : scope === "application" ? summaries.some(value => value?.application) : summaries.some(value => value?.production && value.application)); return item.kind === kind && (!nodeFilter.isActive || direct || ids.some(id => nodeFilter.matchingPathwayIds.has(id))) && (!search || haystack.includes(search.toLocaleLowerCase())) && (status === "all" || item.status === status) && (nodeState === "all" || (nodeState === "has" ? !hasNoNodes(item) : hasNoNodes(item))) && scopePass; }).sort((a, b) => { if (sort === "scope") { const aScope = scopeSummary(a, store.pathways); const bScope = scopeSummary(b, store.pathways); return bScope.production - aScope.production || bScope.application - aScope.application; } return sort === "pathways" ? derivedPathwayIds(b, store.pathways).length - derivedPathwayIds(a, store.pathways).length : (a.status === "review_pending" ? 0 : 1) - (b.status === "review_pending" ? 0 : 1) || +new Date(b.matched_at) - +new Date(a.matched_at); }), [store.paperPatentMatches, store.pathways, kind, search, status, scope, nodeState, sort, nodeFilter.feedstock, nodeFilter.product]);
  useEffect(() => setSelected([]), [nodeFilter.feedstock, nodeFilter.product]);
  const AddIcon = kind === "paper" ? FileText : ScrollText; const singular = kind === "paper" ? "paper" : "patent"; const plural = kind === "paper" ? "papers" : "patents";
  const total = store.paperPatentMatches.filter(item => item.kind === kind).length;
  const filtersActive = Boolean(search || status !== "all" || nodeState !== "all" || scope !== "all" || sort !== "default");
  return <><SectionToolbar title={kind === "paper" ? "Papers" : "Patents"} description={kind === "paper" ? "Inspect publication matches proposed for each Pathway." : "Inspect patent matches proposed for each Pathway."} filtersActive={filtersActive} onReset={() => { setSearch(""); setStatus("all"); setNodeState("all"); setScope("all"); setSort("default"); }} count={filtered.length} total={total} actions={<SplitAddButton label={`Add ${singular}`} icon={AddIcon} onClick={onAdd} ariaLabel={`More add ${singular} options`} items={[{ label: kind === "paper" ? "Single paper by DOI" : "Single patent by ID", icon: AddIcon, onSelect: onAdd }, { label: `Bulk add ${plural}…`, icon: Upload, onSelect: onBulkAdd }, { label: "Download bulk template", icon: Download, onSelect: () => downloadBulkEvidenceTemplate(kind), separatorBefore: true }]} />} filters={<><SectionSearch placeholder={`Search ${plural} and node values…`} value={search} onChange={setSearch} /><SectionFilterSelect value={status} onChange={setStatus} label="Status"><SelectItem value="all">All statuses</SelectItem><SelectItem value="review_pending">Review pending</SelectItem><SelectItem value="accepted">Accepted</SelectItem><SelectItem value="rejected">Rejected</SelectItem></SectionFilterSelect><SectionFilterSelect value={nodeState} onChange={setNodeState} label="Nodes"><SelectItem value="all">All nodes</SelectItem><SelectItem value="has">Has nodes</SelectItem><SelectItem value="none">No nodes</SelectItem></SectionFilterSelect><SectionFilterSelect value={scope} onChange={value => setScope(value as ScopeFilter)} label="Scope"><SelectItem value="all">All scopes</SelectItem><SelectItem value="production">Production in any pathway</SelectItem><SelectItem value="application">Application in any pathway</SelectItem><SelectItem value="both">Both in same pathway</SelectItem><SelectItem value="none">No derived pathway</SelectItem></SectionFilterSelect></>} bulkBar={<SectionBulkBar count={selected.length} onClear={() => setSelected([])}><Button variant="outline" size="sm" className="h-7 text-[10px] text-primary" onClick={() => onDecision(selected, "accepted")}>Accept</Button><Button variant="outline" size="sm" className="h-7 text-[10px] text-destructive" onClick={() => onDecision(selected, "rejected")}>Reject</Button></SectionBulkBar>} />
  <div className="overflow-x-auto"><Table className="min-w-[1820px]"><TableHeader><TableRow><TableHead className="sticky left-0 z-20 w-9 min-w-9 bg-background"><Checkbox checked={filtered.length > 0 && filtered.every(item => selected.includes(item.id))} onCheckedChange={checked => setSelected(checked ? filtered.map(item => item.id) : [])} /></TableHead><TableHead>Title</TableHead><TableHead>{kind === "paper" ? "DOI" : "Patent ID"}</TableHead><TableHead>{kind === "paper" ? "Authors" : "Assignee"}</TableHead><TableHead>Year</TableHead><TableHead>Matched nodes</TableHead><TableHead><Button variant="ghost" className="h-7 px-0 text-[10px]" onClick={() => setSort("pathways")}>Pathways<ArrowUpDown className="ml-1 h-3 w-3" /></Button></TableHead><TableHead className="min-w-36 whitespace-nowrap"><Button variant="ghost" className="h-7 px-0 text-[10px]" onClick={() => setSort("scope")}>Scope<ArrowUpDown className="ml-1 h-3 w-3" /></Button></TableHead><TableHead>Matched</TableHead><TableHead className="min-w-[9.5rem] whitespace-nowrap">Status</TableHead><TableHead>Status changed</TableHead><TableHead>Note</TableHead><TableHead className="sticky right-0 z-20 min-w-32 bg-background text-right">Actions</TableHead></TableRow></TableHeader><TableBody>{filtered.map(item => { const statusChanged = item.status_changed_at === item.matched_at ? null : item.status_changed_at; return <TableRow key={item.id}><TableCell className="sticky left-0 z-10 bg-background"><Checkbox checked={selected.includes(item.id)} onCheckedChange={checked => setSelected(rows => checked ? [...new Set([...rows, item.id])] : rows.filter(id => id !== item.id))} /></TableCell><TableCell><Button variant="link" className="h-auto max-w-60 justify-start p-0 text-left text-xs" onClick={() => onDetail(item.id)}><Truncated value={item.title} className="max-w-60" /></Button></TableCell><TableCell><a href={externalUrl(item)} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 font-mono text-[10px] text-primary hover:underline">{item.external_id}<ExternalLink className="h-2.5 w-2.5" /></a></TableCell><TableCell><Truncated value={item.authors_or_assignee} /></TableCell><TableCell><ValueCell value={item.year} /></TableCell><TableCell className="max-w-96"><NodeChips nodes={item.nodes} compact /></TableCell><TableCell><DerivedPathwaysForRecord match={item} /></TableCell><TableCell className="min-w-36 whitespace-nowrap"><ScopeSummary match={item} /></TableCell><TableCell className="font-mono text-[10px]">{format(new Date(item.matched_at), "dd MMM yyyy")}</TableCell><TableCell className="min-w-[9.5rem] whitespace-nowrap"><ReviewStatusChip status={item.status} /></TableCell><TableCell className="font-mono text-[10px]"><ValueCell value={statusChanged ? format(new Date(statusChanged), "dd MMM yyyy") : null} /></TableCell><TableCell><Truncated value={item.note} /></TableCell><TableCell className="sticky right-0 z-10 bg-background"><div className="flex justify-end gap-1">{item.status !== "accepted" && <Button variant="ghost" size="icon" className="h-7 w-7 text-primary" aria-label={`Accept ${item.id}`} onClick={() => onDecision([item.id], "accepted")}><Check className="h-3.5 w-3.5" /></Button>}{item.status !== "rejected" && <Button variant="ghost" size="icon" className="h-7 w-7 text-destructive" aria-label={`Reject ${item.id}`} onClick={() => onDecision([item.id], "rejected")}><X className="h-3.5 w-3.5" /></Button>}<DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" className="h-7 w-7" aria-label={`More actions for ${item.id}`}><MoreHorizontal className="h-3.5 w-3.5" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onClick={() => onEdit(item.id)}>Edit nodes</DropdownMenuItem><DropdownMenuItem onClick={() => openHistory(entityType, item.id)}><History className="mr-2 h-3.5 w-3.5" />History</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></TableCell></TableRow>; })}{filtered.length === 0 && <TableRow><TableCell colSpan={13} className="p-0">{nodeFilter.isActive ? <NodeFilterEmpty rows={`${kind} matches`} /> : <div className="flex h-32 flex-col items-center justify-center gap-3 text-xs text-muted-foreground"><span>No {kind} matches fit these filters.</span><div className="flex gap-2"><Button size="sm" onClick={onAdd}><AddIcon className="mr-1 h-3.5 w-3.5" />Add {singular}</Button><Button size="sm" variant="outline" onClick={onBulkAdd}><Upload className="mr-1 h-3.5 w-3.5" />Bulk add {plural}</Button></div></div>}</TableCell></TableRow>}</TableBody></Table></div></>;
}

function DecisionDialog({ kind, target, onClose }: { kind: LookupKind; target: DecisionTarget; onClose: () => void }) { const store = useHitlStore(); const [note, setNote] = useState(""); useEffect(() => { if (target) setNote(""); }, [target]); const first = target?.ids.length === 1 ? store.paperPatentMatches.find(item => item.id === target.ids[0]) : null; const save = () => { if (!target) return; target.ids.forEach(id => { const item = store.paperPatentMatches.find(row => row.id === id); if (item && item.status !== target.status) store.recordChange({ entity_type: kind === "paper" ? "paper_match" : "patent_match", entity_id: id, field: "status", prior_value: item.status, new_value: target.status, operation: target.status === "accepted" ? "accept" : "reject", note: note.trim() || null }); }); toast.success("Decision recorded. Signal captured for matching."); onClose(); }; return <Dialog open={target !== null} onOpenChange={open => { if (!open) onClose(); }}><DialogContent><DialogHeader><DialogTitle>{target?.status === "accepted" ? "Accept evidence match" : "Reject evidence match"}</DialogTitle><DialogDescription>{first ? <span className="space-y-2"><span className="block">{first.title} · {first.external_id}</span><span className="flex flex-wrap gap-2"><NodeChips nodes={first.nodes} compact /><DerivedPathwaysForRecord match={first} /><ScopeSummary match={first} /></span></span> : `${target?.ids.length ?? 0} matches`}</DialogDescription></DialogHeader>{target && <div className="space-y-4"><ReviewStatusChip status={target.status} /><div><Label>Note (optional)</Label><Textarea className="mt-1 text-xs" value={note} onChange={event => setNote(event.target.value)} /></div></div>}<DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button onClick={save}>Confirm</Button></DialogFooter></DialogContent></Dialog>; }

function EditNodesDialog({ kind, matchId, onClose }: { kind: LookupKind; matchId: string | null; onClose: () => void }) { const store = useHitlStore(); const item = store.paperPatentMatches.find(row => row.id === matchId); const [nodes, setNodes] = useState<MatchNodes>(emptyMatchNodes()); const [note, setNote] = useState(""); useEffect(() => { if (item) { setNodes({ ...item.nodes }); setNote(item.note ?? ""); } }, [matchId]); const changedPositions = item ? matchNodePositions.filter(position => normalize(item.nodes[position]) !== normalize(nodes[position])) : []; const save = () => { if (!item) return; const entity_type = kind === "paper" ? "paper_match" : "patent_match"; changedPositions.forEach(position => store.recordChange({ entity_type, entity_id: item.id, field: `nodes.${position}`, prior_value: item.nodes[position], new_value: nodes[position]?.trim() || null, operation: "update", note: note.trim() || null })); if ((item.note ?? "") !== note.trim()) store.recordChange({ entity_type, entity_id: item.id, field: "note", prior_value: item.note, new_value: note.trim() || null, operation: "update", note: note.trim() || null }); const summary = scopeSummary({ nodes }, store.pathways); toast.success(`Nodes updated · ${summary.production} production · ${summary.application} application`); onClose(); }; return <Dialog open={matchId !== null} onOpenChange={open => { if (!open) onClose(); }}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>Edit nodes</DialogTitle><DialogDescription>{item ? `${item.title} · ${item.external_id}` : "Update matched node positions."}</DialogDescription></DialogHeader>{item && <MatchEditor nodes={nodes} note={note} onNodes={setNodes} onNote={setNote} />}{hasNoNodes({ nodes }) && <p className="text-xs text-warning-foreground">Link without nodes?</p>}<DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={!item || (!changedPositions.length && (item.note ?? "") === note.trim())} onClick={save}>Save changes</Button></DialogFooter></DialogContent></Dialog>; }

type FetchState = "idle" | "fetching" | "error" | "success";
function LookupDialog({ kind, open, onClose, onOpenExisting }: { kind: LookupKind; open: boolean; onClose: () => void; onOpenExisting: (id: string) => void }) { const store = useHitlStore(); const [externalId, setExternalId] = useState(""); const [state, setState] = useState<FetchState>("idle"); const [result, setResult] = useState<LookupResult | null>(null); const [error, setError] = useState(""); const [showMore, setShowMore] = useState(false); const [nodes, setNodes] = useState<MatchNodes>(emptyMatchNodes()); const [note, setNote] = useState(""); useEffect(() => { if (!open) return; setExternalId(""); setState("idle"); setResult(null); setError(""); setShowMore(false); setNodes(emptyMatchNodes()); setNote(""); }, [open, kind]); const duplicate = store.paperPatentMatches.find(item => item.external_id.toLocaleLowerCase() === externalId.trim().toLocaleLowerCase()); const fetchRecord = async () => { setState("fetching"); setError(""); setResult(null); try { setResult(kind === "paper" ? await lookupDoi(externalId) : await lookupPatent(externalId)); setState("success"); } catch (reason) { setError(reason instanceof Error ? reason.message : "Lookup failed"); setState("error"); } }; const save = () => { if (!result || duplicate) return; const now = new Date().toISOString(); const id = nextId(store.paperPatentMatches.map(item => item.id)); const record: PaperPatentMatch = { id, kind, external_id: externalId.trim(), title: result.title, nodes, status: "accepted", matched_at: now, note: note.trim() || null, year: result.year, authors_or_assignee: result.authors_or_assignee, abstract: result.abstract, source: result.source, created_at: now, updated_at: now, status_changed_at: now, last_actor: store.currentUser.name, trace_id: null }; store.recordChange({ entity_type: kind === "paper" ? "paper_match" : "patent_match", entity_id: id, field: null, prior_value: null, new_value: record, operation: "link_add", note: note.trim() || null }); const count = derivedPathwayIds(record, store.pathways).length; toast.success(`${kind === "paper" ? "Paper" : "Patent"} ${record.external_id} linked · ${count} ${count === 1 ? "pathway" : "pathways"}`); onClose(); }; return <Dialog open={open} onOpenChange={value => { if (!value) onClose(); }}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>Add {kind === "paper" ? "paper by DOI" : "patent by ID"}</DialogTitle><DialogDescription>Fetch a local mock record, then set zero to four node positions.</DialogDescription></DialogHeader><div className="space-y-5"><div><Label>{kind === "paper" ? "DOI" : "Patent ID"}</Label><div className="mt-1 flex gap-2"><Input disabled={state === "fetching"} value={externalId} onChange={event => { setExternalId(event.target.value); if (state !== "fetching") setState("idle"); }} /><Button disabled={!externalId.trim() || state === "fetching" || Boolean(duplicate)} onClick={() => void fetchRecord()}>{state === "fetching" && <Loader2 className="mr-1 h-4 w-4 animate-spin" />}{state === "fetching" ? "Fetching" : "Fetch"}</Button></div>{duplicate && <div className="mt-2 flex items-center justify-between rounded-md border border-destructive/30 bg-destructive/5 p-2 text-xs text-destructive"><span>Already exists: {duplicate.id}</span><Button variant="link" className="h-auto p-0 text-xs" onClick={() => { onClose(); onOpenExisting(duplicate.id); }}>Open</Button></div>}{state === "error" && <p className="mt-2 text-xs text-destructive">{error}</p>}</div>{state === "success" && result && <><div className="space-y-2 rounded-md border p-4"><div className="flex items-center gap-2"><KindChip kind={kind} /><Badge variant="outline" className="inline-flex h-6 items-center gap-1 whitespace-nowrap px-2 text-xs font-normal">{result.source}</Badge><span className="text-[10px] text-muted-foreground">{result.year}</span></div><h3 className="text-sm font-semibold">{result.title}</h3><p className="text-xs text-muted-foreground">{kind === "paper" ? "Authors" : "Assignee"}: {result.authors_or_assignee}</p><p className={cn("text-xs leading-relaxed text-muted-foreground", !showMore && "line-clamp-3")}>{result.abstract}</p><Button variant="link" className="h-auto p-0 text-[10px]" onClick={() => setShowMore(value => !value)}>{showMore ? "Show less" : "Show more"}</Button></div><MatchEditor nodes={nodes} note={note} onNodes={setNodes} onNote={setNote} /></>}</div><DialogFooter>{hasNoNodes({ nodes }) && state === "success" && <span className="mr-auto text-xs text-warning-foreground">Link without nodes?</span>}<Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={state !== "success" || !result || Boolean(duplicate)} onClick={save}><Plus className="mr-1 h-4 w-4" />Link {kind}</Button></DialogFooter></DialogContent></Dialog>; }

type BulkFetchStatus = "pending" | "fetching" | "fetched" | "invalid" | "not_found" | "exists" | "duplicate" | "cancelled";
type BulkOutcome = "linked" | "linked_no_nodes" | "exists" | "fetch_failed" | "invalid" | "duplicate";
interface BulkRow { key: string; externalId: string; nodes: MatchNodes; initialNodes: MatchNodes; note: string; initialNote: string; fetchStatus: BulkFetchStatus; result: LookupResult | null; existingId: string | null; outcome?: BulkOutcome; recordId?: string; pathwayCount?: number; }
const cleanExternalId = (value: string, kind: LookupKind) => kind === "paper" ? value.trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i, "") : value.trim().toUpperCase();
const validExternalId = (value: string, kind: LookupKind) => kind === "paper" ? /^10\.\d{4,9}\/\S+$/i.test(value) : /^[A-Z]{2}[A-Z0-9]{6,12}$/.test(value);
const statusLabel: Record<BulkFetchStatus, string> = { pending: "Pending", fetching: "Fetching", fetched: "Fetched", invalid: "Invalid format", not_found: "Not found", exists: "Already exists", duplicate: "Duplicate in list", cancelled: "Not fetched" };
const resultLabel: Record<BulkOutcome, string> = { linked: "Linked", linked_no_nodes: "Linked · no nodes", exists: "Already exists", fetch_failed: "Not created · fetch failed", invalid: "Not created · invalid format", duplicate: "Not created · duplicate" };
function StatusBadge({ value }: { value: BulkFetchStatus }) { const tone = value === "fetched" ? "border-primary/30 bg-primary/10 text-primary" : value === "invalid" || value === "not_found" ? "border-destructive/30 bg-destructive/10 text-destructive" : "text-muted-foreground"; return <Badge variant="outline" className={cn("inline-flex h-6 items-center gap-1 whitespace-nowrap px-2 text-xs font-normal", tone)}>{statusLabel[value]}</Badge>; }

function BulkAddDialog({ kind, open, onClose, onOpenExisting }: { kind: LookupKind; open: boolean; onClose: () => void; onOpenExisting: (id: string) => void }) {
  const store = useHitlStore(); const [step, setStep] = useState(1); const [paste, setPaste] = useState(""); const [rows, setRows] = useState<BulkRow[]>([]); const [fetchedCount, setFetchedCount] = useState(0); const [pendingReview, setPendingReview] = useState(false); const [allNodes, setAllNodes] = useState<MatchNodes>(emptyMatchNodes()); const [applyPositions, setApplyPositions] = useState<Record<keyof MatchNodes, boolean>>({ feedstock: false, process: false, product: false, application: false }); const [allNote, setAllNote] = useState(""); const [uploadError, setUploadError] = useState(""); const cancelRef = useRef(false); const inputRef = useRef<HTMLInputElement>(null);
  const title = kind === "paper" ? "Bulk add papers" : "Bulk add patents";
  const reset = () => { cancelRef.current = true; setStep(1); setPaste(""); setRows([]); setFetchedCount(0); setPendingReview(false); setAllNodes(emptyMatchNodes()); setApplyPositions({ feedstock: false, process: false, product: false, application: false }); setAllNote(""); setUploadError(""); };
  useEffect(() => { if (open) reset(); }, [open, kind]);
  const buildRows = (items: { id: string; nodes: MatchNodes; note?: string }[]) => { const seen = new Set<string>(); return items.slice(0, 200).map((item, index) => { const externalId = cleanExternalId(item.id, kind); const key = normalize(externalId); const duplicate = seen.has(key); if (!duplicate) seen.add(key); const existing = store.paperPatentMatches.find(match => normalize(match.external_id) === key); const fetchStatus: BulkFetchStatus = duplicate ? "duplicate" : !validExternalId(externalId, kind) ? "invalid" : existing ? "exists" : "pending"; const nodes = { ...item.nodes }; const note = item.note?.trim() ?? ""; return { key: `${index}-${key}`, externalId, nodes, initialNodes: { ...nodes }, note, initialNote: note, fetchStatus, result: null, existingId: existing?.id ?? null } satisfies BulkRow; }); };
  const parsePaste = (text: string) => text.split(/\r?\n/).filter(line => line.trim()).map(line => { const [id = "", feedstock = "", process = "", product = "", application = ""] = line.split(";"); return { id, nodes: { feedstock: feedstock.trim() || null, process: process.trim() || null, product: product.trim() || null, application: application.trim() || null } }; });
  const pasteItems = parsePaste(paste); const pasteRows = useMemo(() => buildRows(parsePaste(paste)), [paste, kind, store.paperPatentMatches]); const activeRows = rows.length ? rows : pasteRows; const duplicates = activeRows.filter(row => row.fetchStatus === "duplicate").length; const eligibleRows = activeRows.filter(row => row.fetchStatus === "pending" || row.fetchStatus === "fetched" || row.fetchStatus === "not_found" || row.fetchStatus === "cancelled"); const overLimit = pasteItems.length > 200;
  const beginNodes = () => { setRows(activeRows.map(row => ({ ...row, nodes: { ...row.initialNodes }, note: row.initialNote }))); setStep(2); };
  const fetchRows = async (sourceRows: BulkRow[], retryOnly = false) => { cancelRef.current = false; setStep(3); const fetchable = sourceRows.filter(row => retryOnly ? row.fetchStatus === "not_found" || row.fetchStatus === "cancelled" : row.fetchStatus === "pending" || row.fetchStatus === "not_found" || row.fetchStatus === "cancelled"); let completed = sourceRows.filter(row => row.fetchStatus === "fetched").length; setFetchedCount(completed); const working = sourceRows.map(row => ({ ...row })); setRows(working); for (const sourceRow of fetchable) { const index = working.findIndex(row => row.key === sourceRow.key); if (index < 0) continue; const row = working[index]; if (cancelRef.current) { for (const remaining of working) if (remaining.fetchStatus === "pending") remaining.fetchStatus = "cancelled"; setRows([...working]); break; } row.fetchStatus = "fetching"; setRows([...working]); try { row.result = kind === "paper" ? await lookupDoi(row.externalId, 150) : await lookupPatent(row.externalId, 150); row.fetchStatus = "fetched"; } catch { row.result = null; row.fetchStatus = "not_found"; } completed += 1; setFetchedCount(completed); setRows([...working]); } };
  const readUpload = async (file: File) => { const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" }); const sheet = workbook.Sheets[workbook.SheetNames[0]]; if (!sheet) return; const raw = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, { defval: "" }); const required = ["ID", "Feedstock", "Process", "Product", "Application", "Note"]; const headers = Object.keys(raw[0] ?? {}); const missing = required.filter(header => !headers.includes(header)); if (missing.length) { setUploadError(`Missing headers: ${missing.join(", ")}`); setRows([]); return; } setUploadError(""); setRows(buildRows(raw.map(row => ({ id: String(row.ID), nodes: { feedstock: String(row.Feedstock).trim() || null, process: String(row.Process).trim() || null, product: String(row.Product).trim() || null, application: String(row.Application).trim() || null }, note: String(row.Note) })).filter(row => row.id.trim()))); setPaste(""); };
  const updateRow = (key: string, patch: Partial<BulkRow>) => setRows(current => current.map(row => row.key === key ? { ...row, ...patch } : row));
  const fetchedRows = rows.filter(row => row.fetchStatus === "fetched"); const withoutNodes = fetchedRows.filter(row => hasNoNodes(row)).length;
  const linkRows = () => { const batchId = `bulk-${Date.now()}`; const now = new Date().toISOString(); const occupied = new Set(store.paperPatentMatches.map(item => normalize(item.external_id))); let numericId = Math.max(0, ...store.paperPatentMatches.map(item => Number(item.id.match(/\d+/)?.[0] ?? 0))); const linkedRows = rows.map(row => { if (row.fetchStatus === "exists") return { ...row, outcome: "exists" as const }; if (row.fetchStatus === "invalid") return { ...row, outcome: "invalid" as const }; if (row.fetchStatus === "duplicate") return { ...row, outcome: "duplicate" as const }; if (row.fetchStatus !== "fetched" || !row.result) return { ...row, outcome: "fetch_failed" as const }; const key = normalize(row.externalId); if (occupied.has(key)) return { ...row, outcome: "exists" as const }; occupied.add(key); numericId += 1; const id = `pp-${String(numericId).padStart(3, "0")}`; const note = [row.note.trim(), `batch ${batchId}`].filter(Boolean).join(" · "); const nodes = Object.fromEntries(matchNodePositions.map(position => [position, row.nodes[position]?.trim() || null])) as unknown as MatchNodes; const record: PaperPatentMatch = { id, kind, external_id: row.externalId, title: row.result.title, year: row.result.year ?? null, authors_or_assignee: row.result.authors_or_assignee ?? null, abstract: row.result.abstract ?? null, source: row.result.source ?? null, nodes, status: pendingReview ? "review_pending" : "accepted", matched_at: now, trace_id: null, note, created_at: now, updated_at: now, status_changed_at: now, last_actor: store.currentUser.name }; store.recordChange({ entity_type: kind === "paper" ? "paper_match" : "patent_match", entity_id: id, field: null, prior_value: null, new_value: record, operation: "link_add", note }); return { ...row, outcome: hasNoNodes(record) ? "linked_no_nodes" as const : "linked" as const, recordId: id, pathwayCount: derivedPathwayIds(record, store.pathways).length }; }); setRows(linkedRows); setStep(4); };
  const linkedCount = rows.filter(row => row.outcome === "linked" || row.outcome === "linked_no_nodes").length; const close = () => { const skipped = rows.filter(row => row.outcome === "exists").length; const errors = rows.filter(row => row.outcome === "fetch_failed").length; if (step === 4) toast.success(`${linkedCount} linked · ${skipped} skipped · ${errors} errors`); reset(); onClose(); };
  const exportCsv = () => { const values = [["ID", "Outcome", "Record ID", "Pathways", "Feedstock", "Process", "Product", "Application", "Note"], ...rows.map(row => [row.externalId, row.outcome ? resultLabel[row.outcome] : "Not created", row.recordId ?? "", String(row.pathwayCount ?? ""), row.nodes.feedstock ?? "", row.nodes.process ?? "", row.nodes.product ?? "", row.nodes.application ?? "", row.note])]; const csv = values.map(line => line.map(value => `"${String(value).replace(/"/g, '""')}"`).join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${kind}-bulk-results.csv`; anchor.click(); URL.revokeObjectURL(url); };
  const counts = (values: BulkFetchStatus[]) => values.map(value => `${rows.filter(row => row.fetchStatus === value).length} ${statusLabel[value].toLocaleLowerCase()}`).join(" · ");
  return <Dialog open={open} onOpenChange={value => { if (!value) close(); }}><DialogContent className="flex max-h-[94vh] w-[min(96vw,1200px)] max-w-none flex-col overflow-hidden"><DialogHeader><DialogTitle>{title}</DialogTitle><DialogDescription>Add identifiers and nodes first, then fetch up to 200 records in one shared audited batch.</DialogDescription></DialogHeader><div className="grid grid-cols-4 border-b pb-3">{["Identifiers", "Nodes", "Fetch", "Result"].map((label, index) => <div key={label} className={cn("border-b-2 pb-2 text-center text-xs font-medium", step === index + 1 ? "border-primary text-foreground" : step > index + 1 ? "border-primary/40 text-foreground" : "border-border text-muted-foreground")}>{index + 1}. {label}</div>)}</div><div className="min-h-0 flex-1 overflow-y-auto py-1">
    {step === 1 && <Tabs defaultValue="paste"><TabsList className="mb-4"><TabsTrigger value="paste">Paste</TabsTrigger><TabsTrigger value="upload">Upload</TabsTrigger></TabsList><TabsContent value="paste" className="space-y-2"><Textarea value={paste} onChange={event => { setPaste(event.target.value); setRows([]); }} placeholder="One record per line: ID; Feedstock; Process; Product; Application" className="min-h-52 font-mono text-xs" /><p className="text-xs text-muted-foreground">10.1016/j.biortech.2024.10442;;Fermentation;Lactic acid;</p><p className="text-xs text-muted-foreground">{activeRows.length - duplicates} identifiers · {duplicates} duplicates removed</p>{overLimit && <p className="text-xs text-destructive">Maximum 200 per batch</p>}</TabsContent><TabsContent value="upload" className="space-y-4"><div className="flex min-h-44 flex-col items-center justify-center gap-3 rounded-md border border-dashed"><FileSpreadsheet className="h-7 w-7 text-muted-foreground" /><p className="text-xs text-muted-foreground">Drop a .xlsx or .csv file here, or choose a file.</p><Input ref={inputRef} type="file" accept=".xlsx,.csv" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void readUpload(file); }} /><Button variant="outline" size="sm" onClick={() => inputRef.current?.click()}>Choose file</Button><Button variant="link" size="sm" onClick={() => downloadBulkEvidenceTemplate(kind)}><Download className="mr-1 h-3 w-3" />Download template</Button></div>{uploadError && <p className="text-xs text-destructive">{uploadError}</p>}</TabsContent><div className="mt-4 overflow-x-auto rounded-md border"><Table><TableHeader><TableRow><TableHead>ID</TableHead><TableHead>Validation</TableHead><TableHead>Nodes</TableHead><TableHead>Note</TableHead></TableRow></TableHeader><TableBody>{activeRows.slice(0, 200).map(row => <TableRow key={row.key}><TableCell className="font-mono text-xs">{row.externalId}</TableCell><TableCell><StatusBadge value={row.fetchStatus} />{row.existingId && <Button variant="link" className="ml-1 h-auto p-0 text-xs" onClick={() => onOpenExisting(row.existingId ?? "")}>Open {row.existingId}</Button>}</TableCell><TableCell><NodeChips nodes={row.initialNodes} compact /></TableCell><TableCell><ValueCell value={row.initialNote || null} /></TableCell></TableRow>)}</TableBody></Table></div></Tabs>}
    {step === 2 && <div className="space-y-4"><div className="space-y-3 rounded-md border bg-muted/30 p-3"><Label className="text-xs">Apply to all rows</Label><NodeFields value={allNodes} onChange={setAllNodes} compact /><div className="flex flex-wrap gap-4">{matchNodePositions.map(position => <label key={position} className="flex items-center gap-2 text-xs"><Checkbox checked={applyPositions[position]} onCheckedChange={checked => setApplyPositions(current => ({ ...current, [position]: checked === true }))} />Apply {MATCH_NODE_LABELS[position]}</label>)}</div><div className="flex gap-2"><Input className="h-8 text-xs" placeholder="Note" value={allNote} onChange={event => setAllNote(event.target.value)} /><Button variant="outline" size="sm" onClick={() => setRows(current => current.map(row => ["pending", "fetched", "not_found", "cancelled"].includes(row.fetchStatus) ? { ...row, nodes: { ...row.nodes, ...Object.fromEntries(matchNodePositions.filter(position => applyPositions[position]).map(position => [position, allNodes[position]])) } } : row))}>Apply selected positions</Button><Button variant="outline" size="sm" onClick={() => setRows(current => current.map(row => ["pending", "fetched", "not_found", "cancelled"].includes(row.fetchStatus) ? { ...row, note: allNote } : row))}>Apply note</Button><Button variant="ghost" size="sm" onClick={() => { setAllNodes(emptyMatchNodes()); setAllNote(""); setRows(current => current.map(row => ["pending", "fetched", "not_found", "cancelled"].includes(row.fetchStatus) ? { ...row, nodes: emptyMatchNodes(), note: "" } : row)); }}>Clear all</Button></div></div><div className="overflow-x-auto"><Table className="min-w-[1200px]"><TableHeader><TableRow><TableHead>ID</TableHead><TableHead className="min-w-[760px]">Matched nodes</TableHead><TableHead>Pathways</TableHead><TableHead className="min-w-64">Note</TableHead></TableRow></TableHeader><TableBody>{rows.filter(row => ["pending", "fetched", "not_found", "cancelled"].includes(row.fetchStatus)).map(row => <TableRow key={row.key}><TableCell className="font-mono text-xs">{row.externalId}</TableCell><TableCell><NodeFields value={row.nodes} onChange={nodes => updateRow(row.key, { nodes })} compact /></TableCell><TableCell className="text-xs">{derivedPathwayIds(row, store.pathways).length}</TableCell><TableCell><Input className="h-9 text-xs" value={row.note} onChange={event => updateRow(row.key, { note: event.target.value })} /></TableCell></TableRow>)}</TableBody></Table></div><label className="flex items-center gap-2 text-xs"><Checkbox checked={pendingReview} onCheckedChange={checked => setPendingReview(checked === true)} />Create as review pending</label></div>}
    {step === 3 && <div className="space-y-4"><div className="flex items-center gap-3"><Progress value={eligibleRows.length ? fetchedCount / eligibleRows.length * 100 : 0} className="flex-1" /><span className="whitespace-nowrap text-xs">{fetchedCount} / {eligibleRows.length} fetched</span>{rows.some(row => row.fetchStatus === "pending" || row.fetchStatus === "fetching") && <Button variant="outline" size="sm" onClick={() => { cancelRef.current = true; }}>Cancel</Button>}</div><div className="overflow-x-auto rounded-md border"><Table className="min-w-[1100px]"><TableHeader><TableRow><TableHead>ID</TableHead><TableHead>Result</TableHead><TableHead>Title</TableHead><TableHead>Year</TableHead><TableHead>{kind === "paper" ? "Authors" : "Assignee"}</TableHead><TableHead>Nodes</TableHead></TableRow></TableHeader><TableBody>{rows.filter(row => !["invalid", "exists", "duplicate"].includes(row.fetchStatus)).map(row => <TableRow key={row.key}><TableCell className="font-mono text-xs">{row.externalId}</TableCell><TableCell><StatusBadge value={row.fetchStatus} /></TableCell><TableCell><Truncated value={row.result?.title ?? null} /></TableCell><TableCell><ValueCell value={row.result?.year ?? null} /></TableCell><TableCell><Truncated value={row.result?.authors_or_assignee ?? null} /></TableCell><TableCell><NodeChips nodes={row.nodes} compact /></TableCell></TableRow>)}</TableBody></Table></div></div>}
    {step === 4 && <div className="overflow-x-auto rounded-md border"><Table><TableHeader><TableRow><TableHead>ID</TableHead><TableHead>Outcome</TableHead><TableHead>Record ID</TableHead><TableHead>Pathways</TableHead></TableRow></TableHeader><TableBody>{rows.map(row => <TableRow key={row.key}><TableCell className="font-mono text-xs">{row.externalId}</TableCell><TableCell><Badge variant="outline" className={cn("inline-flex h-6 items-center gap-1 whitespace-nowrap px-2 text-xs font-normal", (row.outcome === "linked" || row.outcome === "linked_no_nodes") ? "border-primary/30 bg-primary/10 text-primary" : "text-muted-foreground")}>{resultLabel[row.outcome ?? "not_fetched"]}</Badge></TableCell><TableCell>{row.recordId ? <Button variant="link" className="h-auto p-0 font-mono text-xs" onClick={() => onOpenExisting(row.recordId ?? "")}>{row.recordId}</Button> : <ValueCell value={null} />}</TableCell><TableCell><ValueCell value={row.pathwayCount ?? null} /></TableCell></TableRow>)}</TableBody></Table></div>}
  </div><DialogFooter className="border-t pt-3">{step === 1 && <><Button variant="outline" onClick={close}>Cancel</Button><Button disabled={!eligibleRows.length || overLimit} onClick={beginNodes}>Assign nodes to {eligibleRows.length} records</Button></>}{step === 2 && <><Button variant="outline" onClick={() => { if (window.confirm("Return to Identifiers? Node edits made in this step will be discarded.")) { setRows(current => current.map(row => ({ ...row, nodes: { ...row.initialNodes }, note: row.initialNote, result: null, fetchStatus: row.fetchStatus === "fetched" || row.fetchStatus === "not_found" || row.fetchStatus === "cancelled" ? "pending" : row.fetchStatus }))); setStep(1); } }}>Back</Button><Button onClick={() => void fetchRows(rows)}>Fetch {rows.filter(row => row.fetchStatus !== "fetched" && !["invalid", "exists", "duplicate"].includes(row.fetchStatus)).length} records</Button></>}{step === 3 && <><Button variant="outline" onClick={() => setStep(2)}>Back</Button><span className="mr-auto text-xs text-muted-foreground">{counts(["fetched", "not_found", "cancelled"])}</span><Button variant="outline" disabled={!rows.some(row => row.fetchStatus === "not_found" || row.fetchStatus === "cancelled") || rows.some(row => row.fetchStatus === "pending" || row.fetchStatus === "fetching")} onClick={() => void fetchRows(rows, true)}>Retry failed</Button><Button disabled={rows.some(row => row.fetchStatus === "pending" || row.fetchStatus === "fetching")} onClick={linkRows}>Link {fetchedRows.length} records ({withoutNodes} without nodes)</Button></>}{step === 4 && <><span className="mr-auto text-xs text-muted-foreground">{linkedCount} linked</span><Button variant="outline" onClick={exportCsv}><Download className="mr-1 h-4 w-4" />Export results CSV</Button><Button onClick={close}>Close</Button></>}</DialogFooter></DialogContent></Dialog>;
}
function MatchDetailSheet({ kind, matchId, onClose, onDecision, onEdit }: { kind: LookupKind; matchId: string | null; onClose: () => void; onDecision: (ids: string[], status: DecidedStatus) => void; onEdit: (id: string) => void }) { const store = useHitlStore(); const item = store.paperPatentMatches.find(row => row.id === matchId); if (!item) return <Sheet open={false}><SheetContent /></Sheet>; const pathways = derivedPathwayIds(item, store.pathways).map(id => store.pathways.find(pathway => pathway.id === id)).filter((pathway): pathway is NonNullable<typeof pathway> => Boolean(pathway)); const groups = [{ label: "Production", rows: pathways.filter(pathway => { const value = pathwayScope(item, pathway); return value.production && !value.application; }) }, { label: "Application", rows: pathways.filter(pathway => { const value = pathwayScope(item, pathway); return value.application && !value.production; }) }, { label: "Both", rows: pathways.filter(pathway => { const value = pathwayScope(item, pathway); return value.production && value.application; }) }]; const emphasis = filledPositions(item).map(position => item.nodes[position] ?? ""); return <Sheet open={matchId !== null} onOpenChange={open => { if (!open) onClose(); }}><SheetContent className="flex w-[min(96vw,800px)] flex-col gap-0 p-0 sm:max-w-[800px]"><SheetHeader className="border-b px-5 py-4 pr-12"><div className="mb-1 flex flex-wrap items-center gap-2"><KindChip kind={kind} /><Badge variant="outline" className="inline-flex h-6 items-center gap-1 whitespace-nowrap px-2 text-xs font-normal">{item.source ?? "Unknown source"}</Badge><ReviewStatusChip status={item.status} /><ScopeSummary match={item} /></div><SheetTitle className="text-left text-base leading-snug">{item.title}</SheetTitle><SheetDescription className="text-left"><a href={externalUrl(item)} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 font-mono text-[10px] text-primary hover:underline">{item.external_id}<ExternalLink className="h-3 w-3" /></a></SheetDescription></SheetHeader><div className="min-h-0 flex-1 space-y-5 overflow-y-auto px-5 py-4"><section><div className="mb-2 flex items-center justify-between"><h3 className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Matched nodes</h3><Button variant="outline" size="sm" className="h-7 text-[10px]" onClick={() => onEdit(item.id)}>Edit nodes</Button></div><div className="grid grid-cols-4 gap-2 rounded-md border p-3">{matchNodePositions.map(position => <div key={position} className="min-w-0"><div className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">{MATCH_NODE_LABELS[position]}</div><div className={cn("mt-1 truncate text-xs", item.nodes[position] ? "font-semibold" : "text-muted-foreground")}>{item.nodes[position] || "not set"}</div></div>)}</div></section><section><h3 className="mb-2 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Pathways</h3>{pathways.length === 0 ? <p className="py-4 text-xs text-muted-foreground">No pathway matches every filled position.</p> : <div className="space-y-4">{groups.filter(group => group.rows.length).map(group => <div key={group.label}><div className="mb-2 text-xs font-semibold">{group.label} ({group.rows.length})</div><div className="space-y-3">{group.rows.map(pathway => { const value = pathwayScope(item, pathway); const explanations = value.productionPositions.map(position => `Production: ${item.nodes[position]} is the ${MATCH_NODE_LABELS[position]} here`).concat(value.applicationHit ? [`Application: ${item.nodes.application} is the Application here`] : []); return <div key={pathway.id} className="space-y-2"><div className="flex justify-end"><PathwayScopeChips scope={value} /></div><PathwayRef pathwayId={pathway.id} variant="card" emphasisValues={emphasis} showStatus={false} /><p className="text-[10px] text-muted-foreground">{explanations.join(" · ")}</p></div>; })}</div></div>)}</div>}</section><section><h3 className="mb-2 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Record</h3><div className="grid gap-3 rounded-md border p-3 text-xs sm:grid-cols-2"><div><span className="text-muted-foreground">Year</span><p><ValueCell value={item.year} /></p></div><div><span className="text-muted-foreground">{item.kind === "paper" ? "Authors" : "Assignee"}</span><p><ValueCell value={item.authors_or_assignee} /></p></div><div className="sm:col-span-2"><span className="text-muted-foreground">Abstract</span><p className="mt-1 leading-relaxed"><ValueCell value={item.abstract} /></p></div></div></section><section className="grid gap-3 sm:grid-cols-2"><div><h3 className="mb-2 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Dates</h3><div className="space-y-1 font-mono text-[10px]"><p>Matched · {format(new Date(item.matched_at), "dd MMM yyyy, HH:mm:ss")}</p><p>Status changed · {format(new Date(item.status_changed_at), "dd MMM yyyy, HH:mm:ss")}</p></div></div><div><h3 className="mb-2 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Note</h3><p className="mb-1 text-xs"><ValueCell value={item.note} /></p></div></section><div className="flex flex-wrap gap-2 border-y py-3">{item.status !== "accepted" && <Button size="sm" className="h-8 text-[10px]" onClick={() => onDecision([item.id], "accepted")}><Check className="mr-1 h-3 w-3" />Accept</Button>}{item.status !== "rejected" && <Button variant="outline" size="sm" className="h-8 text-[10px] text-destructive" onClick={() => onDecision([item.id], "rejected")}><X className="mr-1 h-3 w-3" />Reject</Button>}<Button variant="outline" size="sm" className="h-8 text-[10px]" onClick={() => onEdit(item.id)}>Edit nodes</Button></div><section><h3 className="mb-2 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">History</h3><RecordHistoryList entityType={kind === "paper" ? "paper_match" : "patent_match"} entityId={item.id} /></section></div></SheetContent></Sheet>; }
